"""[copy of movie/claude_tools/vstyle.py for the paper-plot-animator plugin; adds font fallbacks + automatic signature in save()]
Shared look for the v2 (O-O vs Ne-Ne) and v5 (eta-phi pair correlation) videos:
dark navy gradient background, Helvetica Neue text, caption pills, step indicator, glow helpers,
"Generated by Yongsun" signature (Montserrat Bold Italic, blue).
"""
import os
import numpy as np
import matplotlib
from matplotlib import rcParams
from matplotlib.patches import FancyBboxPatch
from matplotlib.collections import LineCollection
from PIL import Image, ImageDraw, ImageFont

W, H, DPI = 1440, 1080, 100
XL, YL = 6.4, 4.8                      # data half-extent of the full-frame axes
PX = 2 * XL / W                        # data units per pixel

ACCENT = np.array([0.36, 0.72, 1.00])  # blue accent
WHITE = "#f2f4f8"
GREY = "#aab2c4"
DIM = "#6b7384"

def setup():
    # fallbacks: Helvetica Neue lacks arrows, check marks, combining macrons (t̄) etc.
    rcParams["font.family"] = ["Helvetica Neue", "Arial Unicode MS", "DejaVu Sans"]
    rcParams["font.weight"] = "normal"
    rcParams["mathtext.fontset"] = "custom"
    rcParams["mathtext.rm"] = "Helvetica Neue"
    rcParams["mathtext.it"] = "Helvetica Neue:italic"
    rcParams["mathtext.bf"] = "Helvetica Neue:bold"
    rcParams["mathtext.default"] = "regular"

def ease(x):
    x = np.clip(x, 0, 1)
    # clip again: the polynomial can overshoot 1 by ~1e-15, and matplotlib rejects alpha > 1
    return np.clip(x * x * x * (x * (6 * x - 15) + 10), 0, 1)

def ramp(t, a, b):
    return float(ease((t - a) / (b - a)))

# ---------- background ----------
def _background():
    y, x = np.mgrid[0:H, 0:W]
    y = y / (H - 1); x = x / (W - 1)
    top = np.array([0.050, 0.064, 0.110]); bot = np.array([0.010, 0.012, 0.028])
    img = top[None, None, :] * (1 - y)[..., None] + bot[None, None, :] * y[..., None]
    r2 = ((x - 0.5) * 1.333) ** 2 + (y - 0.38) ** 2
    img += np.exp(-r2 / 0.30)[..., None] * np.array([0.030, 0.040, 0.065])[None, None, :]
    return np.clip(img, 0, 1)
BG_ARR = _background()
BG = "#06080f"

def new_figure(plt):
    fig = plt.figure(figsize=(W / DPI, H / DPI), dpi=DPI, facecolor=BG)
    fig.figimage(BG_ARR, xo=0, yo=0, zorder=-10)
    ax = fig.add_axes([0, 0, 1, 1]); ax.set_facecolor("none")
    ax.set_xlim(-XL, XL); ax.set_ylim(-YL, YL); ax.set_aspect("equal"); ax.axis("off")
    return fig, ax

def save(fig, path):
    """Every frame carries the signature: stamped here if the script did not call signature() itself."""
    if not getattr(fig, "_yongsun_sig", False):
        signature(fig)
    fig.savefig(path, dpi=DPI, facecolor=BG)

# ---------- signature ----------
FONT = os.path.expanduser("~/Library/Fonts/Montserrat-Italic-VariableFont_wght.ttf")
def _signature(px=28):
    f = ImageFont.truetype(FONT, px); f.set_variation_by_name(b"Bold Italic")
    t = "Generated by Yongsun"
    x1, y1, x2, y2 = ImageDraw.Draw(Image.new("RGBA", (1, 1))).textbbox((0, 0), t, font=f)
    im = Image.new("RGBA", (x2 - x1 + 4, y2 - y1 + 4), (0, 0, 0, 0))
    ImageDraw.Draw(im).text((2 - x1, 2 - y1), t, font=f, fill=(58, 124, 203, 255))
    return np.asarray(im).astype(float) / 255
SIG = _signature()

def signature(fig):
    """'Generated by Yongsun' bottom right (always on; save() adds it if missing, never twice)."""
    if getattr(fig, "_yongsun_sig", False):
        return
    fig._yongsun_sig = True
    fig.figimage(SIG, xo=W - SIG.shape[1] - 14, yo=12, origin="upper", zorder=100)

# ---------- text helpers ----------
def text(ax, x, y, s, a=1.0, size=20, color=WHITE, weight="normal", ha="center", va="center", z=50, **k):
    if a > 0.01:
        return ax.text(x, y, s, alpha=a, fontsize=size, color=color, weight=weight, ha=ha, va=va, zorder=z, **k)

def pill(ax, x, y, s, a=1.0, size=19, color=WHITE, weight="normal", accent=None, w=None,
         fill=(1, 1, 1, 0.07), edge=(1, 1, 1, 0.14), pad=0.22, z=60, ha="center"):
    """text in a rounded translucent box; accent = colour of a bar on the left edge"""
    if a <= 0.01:
        return
    t = ax.text(x, y, s, alpha=a, fontsize=size, color=color, weight=weight, ha=ha, va="center", zorder=z + 1)
    if w is None:
        fig = ax.figure
        bb = t.get_window_extent(renderer=fig.canvas.get_renderer())
        (x0, y0), (x1, y1) = ax.transData.inverted().transform([[bb.x0, bb.y0], [bb.x1, bb.y1]])
    else:
        x0, x1 = (x - w / 2, x + w / 2) if ha == "center" else ((x, x + w) if ha == "left" else (x - w, x))
        y0, y1 = y - 0.16 * size / 20, y + 0.16 * size / 20
    hgt = max(y1 - y0, 0.34 * size / 20)
    y0 = y - hgt / 2; y1 = y + hgt / 2
    box = FancyBboxPatch((x0, y0), x1 - x0, y1 - y0, boxstyle=f"round,pad={pad},rounding_size={0.16 + 0.5 * pad}",
                         fc=(fill[0], fill[1], fill[2], fill[3] * a), ec=(edge[0], edge[1], edge[2], edge[3] * a),
                         lw=1.0, zorder=z)
    ax.add_patch(box)
    if accent is not None:
        c = np.asarray(matplotlib.colors.to_rgb(accent))
        ax.add_patch(FancyBboxPatch((x0 - pad + 0.02, y0 - pad * 0.45), 0.07, (y1 - y0) + 0.9 * pad,
                                    boxstyle="round,pad=0,rounding_size=0.035", fc=(*c, a), ec="none", zorder=z + 1))
    return box

def steps(ax, labels, active, a=1.0, x0=-XL + 0.35, y=YL - 0.28, width=2.6, color=ACCENT):
    """compact progress bar + 'k/n  label' at the top left"""
    if a <= 0.01:
        return
    n = len(labels); gap = 0.06
    w = (width - gap * (n - 1)) / n
    for i in range(n):
        if i < active:
            fc = (*color, 0.55 * a)
        elif i == active:
            fc = (*color, 1.0 * a)
        else:
            fc = (1, 1, 1, 0.14 * a)
        ax.add_patch(FancyBboxPatch((x0 + i * (w + gap), y - 0.04), w, 0.08, boxstyle="round,pad=0,rounding_size=0.04",
                                    fc=fc, ec="none", zorder=70))
    ax.text(x0, y - 0.22, f"{active + 1}/{n}", fontsize=13.5, color=(*color, a), weight="bold", ha="left", va="center", zorder=70)
    ax.text(x0 + 0.45, y - 0.22, labels[active], fontsize=13.5, color=GREY, alpha=a, ha="left", va="center", zorder=70)

# ---------- glow ----------
def glow_lines(ax, segs, colors, lw, alpha, z=3, passes=((3.2, 0.10), (1.8, 0.22), (1.0, 1.0))):
    """segs: (n, m, 2) polylines; colors: (n, 3) rgb; draws a soft glow then the core line"""
    colors = np.asarray(colors)
    for mult, am in passes:
        c = np.concatenate([colors, np.full((len(colors), 1), alpha * am)], 1)
        ax.add_collection(LineCollection(segs, colors=c, linewidths=lw * mult, zorder=z, capstyle="round"))

def glow_points(ax, xy, s, colors, alpha, z=5, halo=3.0, halo_a=0.18):
    colors = np.asarray(colors)
    xy = np.asarray(xy)
    ax.scatter(xy[:, 0], xy[:, 1], s=s * halo, c=colors, alpha=alpha * halo_a, edgecolors="none", zorder=z)
    ax.scatter(xy[:, 0], xy[:, 1], s=s, c=colors, alpha=alpha, edgecolors="none", zorder=z + 0.01)

def radial_sprite(rgb, n=96, k=3.0):
    y, x = np.mgrid[-1:1:n * 1j, -1:1:n * 1j]
    r2 = x * x + y * y
    a = np.exp(-r2 * k) * np.clip((1 - np.sqrt(r2)) * 4, 0, 1)      # soft edge, no hard cut-off
    return np.dstack([np.broadcast_to(np.asarray(rgb, float), (n, n, 3)), a])

def glow_disc(ax, x, y, r, rgb, a, z=4, k=3.0):
    if a > 0.01:
        ax.imshow(radial_sprite(rgb, k=k) * [1, 1, 1, a], extent=(x - r, x + r, y - r, y + r), zorder=z, interpolation="bilinear")
